const display = document.getElementById('display');
const keys = document.querySelectorAll('.keys button');
let currentNumber = '';
let previousNumber = '';
let operation = '';
let memory = 0;

keys.forEach(key => {
    key.addEventListener('click', () => {
        const keyValue = key.textContent;
        switch (keyValue) {
            case 'C':
                currentNumber = '';
                previousNumber = '';
                operation = '';
                display.value = '';
                break;
            case 'DEL':
                currentNumber = currentNumber.slice(0, -1);
                display.value = currentNumber;
                break;
            case '=':
                calculateResult();
                break;
            case '+':
            case '-':
            case '*':
            case '/':
                operation = keyValue;
                previousNumber = currentNumber;
                currentNumber = '';
                break;
            case 'sin':
            case 'cos':
            case 'tan':
            case 'log':
            case 'ln':
            case '^':
            case 'sqrt':
                calculateTrigonometricResult(keyValue);
                break;
            case 'MC':
                memory = 0;
                break;
            case 'MR':
                currentNumber = memory.toString();
                display.value = currentNumber;
                break;
            case 'M+':
                memory += parseFloat(currentNumber);
                break;
            case 'M-':
                memory -= parseFloat(currentNumber);
                break;
            default:
                currentNumber += keyValue;
                display.value = currentNumber;
        }
    });
});

function calculateResult() {
    let result;
    switch (operation) {
        case '+':
            result = parseFloat(previousNumber) + parseFloat(currentNumber);
            break;
        case '-':
            result = parseFloat(previousNumber) - parseFloat(currentNumber);
            break;
        case '*':
            result = parseFloat(previousNumber) * parseFloat(currentNumber);
            break;
        case '/':
            result = parseFloat(previousNumber) / parseFloat(currentNumber);
            break;
    }
    display.value = result.toString();
}

function calculateTrigonometricResult(operation) {
    let result;
    switch (operation) {
        case 'sin':
            result = Math.sin(parseFloat(currentNumber));
            break;
        case 'cos':
            result = Math.cos(parseFloat(currentNumber));
            break;
        case 'tan':
            result = Math.tan(parseFloat(currentNumber));
            break;
        case 'log':
            result = Math.log10(parseFloat(currentNumber));
            break;
        case 'ln':
            result = Math.log(parseFloat(currentNumber));
            break;
        case '^':
            result = Math.pow(parseFloat(currentNumber), 2);
            break;
        case 'sqrt':
            result = Math.sqrt(parseFloat(currentNumber));
            break;
    }
    display.value = result.toString();
}

